CREATE TABLE IF NOT EXISTS service_connectors(id BIGSERIAL PRIMARY KEY,connector_key VARCHAR(120) NOT NULL UNIQUE,label TEXT NOT NULL,service_type VARCHAR(80) NOT NULL,base_url TEXT,auth_type VARCHAR(40) NOT NULL DEFAULT 'none',capabilities_json TEXT NOT NULL DEFAULT '[]',ui_meta_json TEXT NOT NULL DEFAULT '{}',status VARCHAR(20) NOT NULL DEFAULT 'disabled' CHECK(status IN('disabled','ready','degraded','error')),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS service_connector_credentials(connector_id BIGINT PRIMARY KEY REFERENCES service_connectors(id) ON DELETE CASCADE,credentials_sealed TEXT NOT NULL,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS service_connector_health(connector_id BIGINT PRIMARY KEY REFERENCES service_connectors(id) ON DELETE CASCADE,last_ok_at TIMESTAMP,last_error_at TIMESTAMP,last_http_status INTEGER,last_error_code TEXT,last_error_message TEXT,latency_ms INTEGER,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS service_connector_idempotency(connector_id BIGINT NOT NULL REFERENCES service_connectors(id) ON DELETE CASCADE,idempotency_key VARCHAR(190) NOT NULL,response_json TEXT NOT NULL DEFAULT '{}',expires_at TIMESTAMP NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(connector_id,idempotency_key));
CREATE TABLE IF NOT EXISTS service_connector_cache(connector_id BIGINT NOT NULL REFERENCES service_connectors(id) ON DELETE CASCADE,cache_key VARCHAR(190) NOT NULL,payload_json TEXT NOT NULL,expires_at TIMESTAMP NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(connector_id,cache_key));
CREATE INDEX IF NOT EXISTS idx_connector_health_status ON service_connector_health(last_ok_at,last_error_at);
